package com.daniil.wristlens.phone;
import android.graphics.*;import com.daniil.wristlens.core.WatermarkSpec;import org.junit.*;import org.junit.runner.RunWith;import static org.junit.Assert.*;import org.robolectric.*;import org.robolectric.annotation.*;import java.io.*;import java.nio.*;import java.nio.file.*;import org.json.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class SavedWatermarkTest {
 private byte[] camera()throws Exception{Bitmap b=Bitmap.createBitmap(960,540,Bitmap.Config.ARGB_8888);b.eraseColor(0xff708090);ByteArrayOutputStream out=new ByteArrayOutputStream();assertTrue(b.compress(Bitmap.CompressFormat.JPEG,95,out));b.recycle();return out.toByteArray();}
 @Test public void disabledJpegPreservesEveryOriginalByte()throws Exception{byte[] original=camera();ByteArrayOutputStream out=new ByteArrayOutputStream();PhotoWatermark.write(original,"jpeg",new WatermarkSpec(false,"top_left","white","small",true,true,"yyyy-MM-dd","HH:mm:ss"),0,out);assertArrayEquals(original,out.toByteArray());}
 @Test public void savedPhotoFormatsContainWatermarkPixelsInAllCorners()throws Exception{byte[] source=camera();File dir=new File("build/saved-watermarks");dir.mkdirs();for(String format:new String[]{"jpeg","png","webp"})for(String corner:WatermarkSpec.CORNERS)for(String color:WatermarkSpec.COLORS){ByteArrayOutputStream out=new ByteArrayOutputStream();PhotoWatermark.write(source,format,new WatermarkSpec(true,corner,color,"medium",true,true,"yyyy-MM-dd","HH:mm:ss"),1792782307000L,out);byte[] data=out.toByteArray();try(FileOutputStream f=new FileOutputStream(new File(dir,format+"-"+corner+"-"+color+"."+format))){f.write(data);}Bitmap decoded=ImageDecoder.decodeBitmap(ImageDecoder.createSource(ByteBuffer.wrap(data)),(d,i,s)->d.setAllocator(ImageDecoder.ALLOCATOR_SOFTWARE));int xsum=0,ysum=0,n=0;for(int y=0;y<decoded.getHeight();y++)for(int x=0;x<decoded.getWidth();x++){int red=Color.red(decoded.getPixel(x,y));if(color.equals("white")?red>220:red<30){xsum+=x;ysum+=y;n++;}}assertTrue(format+corner+color,n>40);assertEquals(corner.endsWith("right"),xsum/n>decoded.getWidth()/2);assertEquals(corner.startsWith("bottom"),ysum/n>decoded.getHeight()/2);decoded.recycle();}}
 @Test public void exportAndroidTextTexturesForActualShaderTest()throws Exception{File dir=new File("build/gpu-watermark-input");dir.mkdirs();JSONArray cases=new JSONArray();for(int rotation:new int[]{0,90,180,270})for(String corner:WatermarkSpec.CORNERS)for(String color:WatermarkSpec.COLORS){try(WatermarkOverlay o=new WatermarkOverlay(new WatermarkSpec(true,corner,color,"medium",true,true,"yyyy-MM-dd","HH:mm:ss"),640,480,rotation)){o.update(1792782307000L);String name=rotation+"-"+corner+"-"+color;try(FileOutputStream out=new FileOutputStream(new File(dir,name+".png"))){assertTrue(o.bitmap.compress(Bitmap.CompressFormat.PNG,100,out));}JSONArray vertices=new JSONArray();for(float v:o.vertices)vertices.put(v);cases.put(new JSONObject().put("name",name).put("corner",corner).put("color",color).put("rotation",rotation).put("vertices",vertices));}}Files.write(new File(dir,"cases.json").toPath(),cases.toString(2).getBytes(java.nio.charset.StandardCharsets.UTF_8));assertEquals(32,cases.length());}
}
